import { createMiddleware } from "@tanstack/react-start";
import { supabase } from "./client";
import { isPreviewAuthFallback } from "./previewAuthStorage";

// Deve estar registrado como `functionMiddleware` global em src/start.ts.
//
// Em produção os cookies httpOnly viajam sozinhos em toda chamada de
// server function — nada a anexar. No fallback de preview (localStorage),
// mantém o Authorization: Bearer antigo, que o middleware ainda aceita.
export const attachSupabaseAuth = createMiddleware({ type: "function" }).client(
  async ({ next }) => {
    if (!isPreviewAuthFallback()) return next();
    const { data } = await supabase.auth.getSession();
    const token = data.session?.access_token;
    return next({
      headers: token ? { Authorization: `Bearer ${token}` } : {},
    });
  },
);
